<?php
/** GD Client Portal v3.1 — Client Service Requests & Change Center. */
if(!defined('ABSPATH')) exit;
function gd_client_portal_requests_table(){global $wpdb;return $wpdb->prefix.'gd_service_requests';}
function gd_client_portal_activate_requests_table(){global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$c=$wpdb->get_charset_collate();$t=gd_client_portal_requests_table();dbDelta("CREATE TABLE $t (id bigint(20) unsigned NOT NULL AUTO_INCREMENT,tenant_id bigint(20) unsigned NOT NULL DEFAULT 0,user_id bigint(20) unsigned NOT NULL DEFAULT 0,project_id bigint(20) unsigned NOT NULL DEFAULT 0,type varchar(30) NOT NULL DEFAULT 'service_request',title varchar(255) NOT NULL,description longtext NULL,priority varchar(20) NOT NULL DEFAULT 'normal',status varchar(30) NOT NULL DEFAULT 'new',admin_note longtext NULL,created_at datetime DEFAULT CURRENT_TIMESTAMP,updated_at datetime DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY tenant_id(tenant_id),KEY user_id(user_id),KEY project_id(project_id),KEY status(status)) $c;");}
function gd_client_portal_requests_upgrade(){if(absint(get_option('gd_client_portal_requests_schema_version',0))<1){gd_client_portal_activate_requests_table();update_option('gd_client_portal_requests_schema_version',1);}}
// Schema lifecycle is managed centrally by GDCP_Migration_Manager (v6.8+).
function gd_client_portal_request_access($r,$admin=false){if(!$r||!gd_client_portal_verify_request())return false;if(gd_client_portal_is_platform_admin())return true;$tenant=gd_client_portal_get_current_tenant_id();if($tenant<=0||absint($r->tenant_id)!==$tenant)return false;return $admin?gd_client_portal_user_is_tenant_admin():absint($r->user_id)===gd_client_portal_cached_current_user_id();}
function gd_client_portal_get_requests($limit=50){if(!gd_client_portal_verify_request())return array();return gdcp_request_service()->list($limit);}
function gd_client_portal_request_statuses(){return array('new'=>'New','reviewing'=>'Reviewing','approved'=>'Approved','in_progress'=>'In progress','completed'=>'Completed','declined'=>'Declined');}
function gd_client_portal_request_create(){if(!is_user_logged_in()||!gd_client_portal_verify_request())return new WP_Error('forbidden','Access denied.');check_ajax_referer('gd_client_portal_request','nonce');$tenant=gd_client_portal_get_current_tenant_id();if($tenant<=0&&!gd_client_portal_is_platform_admin())return new WP_Error('tenant','No tenant assigned.');$project_id=absint($_POST['project_id']??0);$type=sanitize_key($_POST['type']??'service_request');if(!in_array($type,array('service_request','change_request','support_request'),true))$type='service_request';$title=sanitize_text_field($_POST['title']??'');$desc=sanitize_textarea_field($_POST['description']??'');$priority=sanitize_key($_POST['priority']??'normal');if(!$title||!$desc)return new WP_Error('required','Please complete the title and description.');if(!in_array($priority,array('low','normal','high','urgent'),true))$priority='normal';if($project_id){$p=gd_client_portal_get_project_by_id($project_id);if(!$p||!gd_client_portal_verify_project_access($p))return new WP_Error('project','Project access denied.');$tenant=absint($p->tenant_id);}global $wpdb;$data=array('tenant_id'=>$tenant,'user_id'=>gd_client_portal_cached_current_user_id(),'project_id'=>$project_id,'type'=>$type,'title'=>$title,'description'=>$desc,'priority'=>$priority,'status'=>'new','created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql'));$id=gdcp_request_service()->create($data);if(!$id)return new WP_Error('db','Could not create request.');if(function_exists('gd_client_portal_create_notification')){ $recipients=array(); $linked=$project_id?gd_client_portal_get_project_by_id($project_id):null; if(function_exists('gd_client_portal_notification_recipients') && $linked) $recipients=gd_client_portal_notification_recipients($linked,gd_client_portal_cached_current_user_id()); else { $users=get_users(array('number'=>-1,'fields'=>'ID','meta_key'=>'gd_client_portal_tenant_id','meta_value'=>$tenant)); foreach($users as $uid){ if(user_can($uid,'gd_client_portal_tenant_admin')) $recipients[]=absint($uid); } } foreach(array_unique($recipients) as $uid) gd_client_portal_create_notification($uid,__('New client request','gd-client-portal'),$title,'service_request',$project_id,$tenant);}do_action('gd_client_portal_service_request_created',$id,$project_id,$tenant);if(function_exists('gd_client_portal_audit_log'))gd_client_portal_audit_log('service_request_created',$title,$project_id,$tenant,$desc,'service_request',$id,array('type'=>$type,'priority'=>$priority));wp_send_json_success(array('id'=>$id,'message'=>__('Request submitted successfully.','gd-client-portal')));}
add_action('wp_ajax_gd_client_portal_request_create','gd_client_portal_request_create');
function gd_client_portal_request_update(){if(!is_user_logged_in()||!gd_client_portal_verify_request())wp_send_json_error(array('message'=>'Access denied.'),403);check_ajax_referer('gd_client_portal_request_admin','nonce');$id=absint($_POST['request_id']??0);$status=sanitize_key($_POST['status']??'');$note=sanitize_textarea_field($_POST['admin_note']??'');$r=gd_client_portal_request_get($id);if(!$r||!gd_client_portal_request_access($r,true))wp_send_json_error(array('message'=>'Access denied.'),403);if(!array_key_exists($status,gd_client_portal_request_statuses()))wp_send_json_error(array('message'=>'Invalid status.'));if(gdcp_request_service()->update_status($id,$status,$note)===false)wp_send_json_error(array('message'=>'Could not update request.'),500);if(function_exists('gd_client_portal_create_notification'))gd_client_portal_create_notification($r->user_id,__('Service request updated','gd-client-portal'),sprintf(__('“%s” is now %s.','gd-client-portal'),$r->title,gd_client_portal_request_statuses()[$status]),'service_request',$r->project_id,$r->tenant_id);if(function_exists('gd_client_portal_audit_log'))gd_client_portal_audit_log('service_request_updated',$r->title,$r->project_id,$r->tenant_id,$note,'service_request',$id,array('status'=>$status));wp_send_json_success(array('message'=>'Updated.'));}
add_action('wp_ajax_gd_client_portal_request_update','gd_client_portal_request_update');
function gd_client_portal_request_get($id){return gdcp_request_service()->get($id);}
function gd_client_portal_render_request_center($atts=array()){if(!is_user_logged_in()||!gd_client_portal_verify_request())return '<div class="gd-request-gate">Please log in to access Service Requests.</div>';$project_id=absint($_GET['request_project']??0);$requests=gd_client_portal_get_requests(100);ob_start();?><div class="gd-request-center"><div class="gd-request-hero"><div><span class="gd-request-eyebrow">Client services</span><h2>Service Request Center</h2><p>Ask for a new service, request a project change, or get support from your team.</p></div><button type="button" class="gd-request-new" id="gd-request-new">New request</button></div><div id="gd-request-form" class="gd-request-form" hidden><div class="gd-request-grid"><label>Request type<select id="gd-request-type"><option value="service_request">New service</option><option value="change_request">Project change</option><option value="support_request">Support</option></select></label><label>Priority<select id="gd-request-priority"><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option><option value="low">Low</option></select></label></div><label>Title<input id="gd-request-title" maxlength="255" placeholder="What do you need?"></label><label>Description<textarea id="gd-request-description" rows="5" placeholder="Explain what you need and any important context..."></textarea></label><?php if($project_id):?><input type="hidden" id="gd-request-project" value="<?php echo intval($project_id);?>"><?php else:?><label>Project ID (optional)<input type="number" min="0" id="gd-request-project" value="0" placeholder="Leave blank for a general request"></label><?php endif;?><div><button type="button" class="gd-request-submit" id="gd-request-submit">Submit request</button> <button type="button" class="gd-request-cancel" id="gd-request-cancel">Cancel</button></div><div id="gd-request-result"></div></div><div class="gd-request-list"><h3>Your requests</h3><?php if(!$requests):?><div class="gd-request-empty">No requests yet.</div><?php else: foreach($requests as $r):?><article class="gd-request-card"><div class="gd-request-card-top"><span class="gd-request-type-badge"><?php echo esc_html(ucwords(str_replace('_',' ',$r->type)));?></span><span class="gd-request-status status-<?php echo esc_attr($r->status);?>"><?php echo esc_html(gd_client_portal_request_statuses()[$r->status]??$r->status);?></span></div><h4><?php echo esc_html($r->title);?></h4><p><?php echo esc_html(wp_trim_words($r->description,28));?></p><div class="gd-request-meta"><span>Priority: <?php echo esc_html(ucfirst($r->priority));?></span><?php if($r->project_id):?><span>Project #<?php echo intval($r->project_id);?></span><?php endif;?><time><?php echo esc_html(wp_date(get_option('date_format'),strtotime($r->created_at)));?></time></div><?php if($r->admin_note):?><div class="gd-request-note"><strong>Team response:</strong> <?php echo esc_html($r->admin_note);?></div><?php endif;?></article><?php endforeach;endif;?></div></div><?php return ob_get_clean();}
add_shortcode('gd_service_requests','gd_client_portal_render_request_center');
function gd_client_portal_request_admin_page(){if(!current_user_can('gd_client_portal_access_admin'))wp_die('Access denied.');$rows=gd_client_portal_get_requests(200);echo '<div class="wrap"><h1>Service Request Center</h1><p>Review client service, change, and support requests.</p><table class="widefat striped"><thead><tr><th>Request</th><th>Client</th><th>Project</th><th>Priority</th><th>Status</th><th>Update</th></tr></thead><tbody>';foreach($rows as $r){$u=gd_client_portal_cached_user($r->user_id);$statuses=gd_client_portal_request_statuses();echo '<tr><td><strong>'.esc_html($r->title).'</strong><br><small>'.esc_html(ucwords(str_replace('_',' ',$r->type))).'</small><p>'.esc_html(wp_trim_words($r->description,20)).'</p></td><td>'.esc_html($u?$u->display_name:'User #'.$r->user_id).'</td><td>'.($r->project_id?'#'.intval($r->project_id):'General').'</td><td>'.esc_html(ucfirst($r->priority)).'</td><td><form class="gd-request-admin-form"><input type="hidden" name="request_id" value="'.intval($r->id).'">'.wp_nonce_field('gd_client_portal_request_admin','_wpnonce',true,false).'<select name="status">';foreach($statuses as $k=>$v)echo '<option value="'.esc_attr($k).'" '.selected($r->status,$k,false).'>'.esc_html($v).'</option>';echo '</select><textarea name="admin_note" placeholder="Team response">'.esc_textarea($r->admin_note).'</textarea><button class="button button-primary" type="submit">Save</button></form></td></tr>';}if(!$rows)echo '<tr><td colspan="6">No requests.</td></tr>';echo '</tbody></table></div>';}
function gd_client_portal_register_request_admin(){add_submenu_page('gd-client-portal','Service Requests','Service Requests','gd_client_portal_access_admin','gd-client-portal-requests','gd_client_portal_request_admin_page');}
add_action('admin_menu','gd_client_portal_register_request_admin',20);
add_action('init',function(){if(function_exists('gd_client_portal_register_dashboard_view'))gd_client_portal_register_dashboard_view('service_requests','gd_client_portal_render_request_center');});
